"""Offline successor to the historical model. No cloud/account discovery."""
import json,pathlib,subprocess,sys
from decimal import Decimal as D, ROUND_HALF_UP
root=pathlib.Path(__file__).resolve().parents[1]
prior=json.loads(subprocess.check_output([sys.executable,str(root/'b1a2/calculate-costs.py')]))
q=lambda x:str(x.quantize(D('.01'),rounding=ROUND_HALF_UP))
cases={}
for name,case in prior['scenarios'].items():
    lines={k:D(v) for k,v in case['linesUsd'].items()}
    removed=lines.pop('temporary_restore_drill')
    base=sum(lines.values()); contingency=base*D('.25'); tax=(base+contingency)*D('.16'); lag=D('1'); residual=D('1'); stress=base+contingency+tax+lag+residual; fx=stress*D('.10')
    cases[name]={'hours':case['hours'],'linesUsd':{k:str(v) for k,v in lines.items()},'removedRestoreDrillAllowanceUsd':q(removed),'baseUsd':q(base),'contingency25PercentUsd':q(contingency),'subtotalUsd':q(base+contingency),'illustrativeTax16PercentUsd':q(tax),'withTaxUsd':q(base+contingency+tax),'delayedBillingAllowanceUsd':q(lag),'residualRetentionAllowanceUsd':q(residual),'stressBeforeFxUsd':q(stress),'illustrativeFx10PercentUsdEquivalent':q(fx),'stressWithFxUsdEquivalent':q(stress+fx),'headroomAgainst30UsdEquivalent':q(D('30')-stress-fx),'twoFailedOrRepeatedRunsStressUsdEquivalent':q(2*(stress+fx)),'repeatWithinSame30Allocation':2*(stress+fx)<=30,'spendingAuthorized':False}
print(json.dumps({'scope':'READINESS_OFFLINE_ESTIMATE_NOT_A_QUOTE','pricingBasis':prior['pricingBasis'],'ownerPlanning':{'allocationUsd':'30.00','sessionMaximumHours':6,'physicalTerminationTargetSeconds':60,'reportingLatencySeparate':True,'humans':1,'separateTechnicalIdentities':True,'b1aPitrDays':1,'restoreDrillB1a':False,'restoreDrillB1bRequired':True},'scenarios':cases,'currencyVerification':{'accountCurrency':None,'actualLocalPerUsd':None,'fxAsOf':None,'fxOwnerApprovalRef':None,'trialEligibilityVerified':False,'creditDeducted':False,'approvedMxnBudget':None,'conversionRule':'Only after separate verification: approved MXN planning amount = 30 USD times owner-approved MXN/USD; alerts round upward to centavos. No FX value supplied here.'},'budgetAlertsAreHardCaps':False,'spendingAuthorized':False,'uncertainties':prior['sensitivities']+['Shared micro SQL tier/connection count, Enterprise availability, private endpoints and exact pricing require account receipts','Failed or repeated six-hour runs are not included as free retries; cumulative costs consume allocation','No hourly price or finite contingency guarantees a spending ceiling; logs/NAT/IPv4/SQL/secrets/AR/KMS and billing lag can continue after compute shutdown','Single supervised operator has common-human custody/kill/billing failure risk; no second human or permanent observer VM is costed','Tax and FX stresses are illustrative, not fiscal advice or approved billing inputs'],'residualDailyGrossUsd':prior['residualDailyGrossUsd']},indent=2))
